#dl-focus {
  position: absolute; inset: 0; overflow: hidden;
  /* enhance.js samples the poster and writes --focus-tint: the view takes its
     colour from the game being downloaded. */
  --accent: var(--focus-tint, var(--primary, #7c8cff));
  --accent-hi: color-mix(in srgb, var(--accent) 72%, #fff);
  --accent-soft: color-mix(in srgb, var(--accent) 16%, transparent);
  --accent-line: color-mix(in srgb, var(--accent) 42%, transparent);
  --accent-ink: #0d1020;
}

// A chart takes the accent of the surface it sits on — the download view
// is tinted from its own game — and falls back to the interface accent.
const local = getComputedStyle(canvas).getPropertyValue('--chart-ink').trim();
const primary = normalizeHex(local) || styles.getPropertyValue('--primary').trim() || THEME_DEFAULTS.accent;

// Baseline grid

// The view borrows its colour from the game: sample the banner and hand
// the result to the stylesheet and to the chart.
const panel = $('#dl-focus');
if (panel) { panel.style.removeProperty('--focus-tint'); panel.style.removeProperty('--chart-ink'); }
if (appid && prefs().dynamic_accent !== false) {
  Accent.sample(bridge.steamHeaderUrl(appid)).then((colour) => {
    if (!colour || !panel || currentKey !== `${appid || ''}|${name || ''}`) return;
    panel.style.setProperty('--focus-tint', colour);
    panel.style.setProperty('--chart-ink', colour);
    window.dispatchEvent(new CustomEvent('librarian:redraw'));
  }).catch(() => {});
}

if (!appid) { drawGenerated(); return; }

